// Font assets: a TTF, OTF or WOFF2 file becomes a versioned library asset with its licence, family, weight, style and
// coverage; it draws at once in the render workers (no restart) and reaches the browser through the bundle; a clip pins
// the font files it was made with, so a new version of the font changes nothing until the clip is repinned.
// The test fonts are generated by scripts/make-test-fonts.mjs (bars and triangles, public domain).

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createCanvas } from '@napi-rs/canvas';
import { tempStudio, EASING, LABEL } from './helpers.js';
import { createStudioServer } from '../src/server/http.js';
import { connect, callTool } from '../scripts/mcp.mjs';
import { parseFont, summarizeCoverage, coverageReport } from '../src/render/glyphs.js';
import { registerFonts } from '../src/render/host.js';
import { createText, fontString, familyOf, fontAliases } from '../src/core/lib/text.js';

const here = dirname(fileURLToPath(import.meta.url));
const FIX = (name) => join(here, 'fixtures', 'fonts', name);
const AUTHOR = 'font-test';
registerFonts();
const filesIn = (dir) => readdirSync(join(dir, 'files'));

/** A text asset with a font and a weight, the way real assets take them. */
const TEXT = `asset({
  description: 'A line of text in the chosen font and weight.',
  tags: ['text', 'test'],
  duration: 2,
  params: {
    text: { type: 'string', default: 'Hello' },
    font: { type: 'font', default: 'Inter' },
    weight: { type: 'integer', default: 400, min: 100, max: 900 },
  },
  render(f, p) {
    const L = f.lib.text.layout(f.ctx, p.text, { font: p.font, weight: p.weight, size: f.height * 0.4, maxWidth: f.safe.width, fit: true, align: 'center' });
    f.ctx.fillStyle = '#ffffff';
    f.lib.text.fill(f.ctx, L, f.safe.x, (f.height - L.height) / 2);
  },
});`;

const clipOf = (font, { weight = 400, text = 'Hello ăș' } = {}) => ({
  width: 320, height: 180, fps: 10, duration: 2,
  tracks: [{ id: 'v', type: 'visual', items: [{ id: 't', asset: 'text', start: 0, duration: 2, params: { text, font, weight } }] }],
});

let t, studio;
const hashOf = async (clip) => (await studio.frameHashes({ clip, times: [1] }))[0].hash;
const add = (o) => studio.fonts.addFont({ author: AUTHOR, license: 'CC0-1.0', ...o });
const refused = (promise, re) => assert.rejects(promise, (/** @type {any} */ e) => { assert.equal(e.name, 'StudioError'); assert.match(e.message, re); return true; });

before(async () => {
  t = tempStudio();
  studio = t.studio;
  await studio.library.createAsset({ slug: 'easing', source: EASING, author: AUTHOR });
  await studio.library.createAsset({ slug: 'text', source: TEXT, author: AUTHOR });
  await studio.library.createAsset({ slug: 'label', source: LABEL, author: AUTHOR });
});
after(async () => { await t.cleanup(); });

// ---- the file readers -----------------------------------------------------------------------------

test('parseFont reads family, weight, style, format and coverage from TTF, OTF and WOFF2', () => {
  const a = parseFont(readFileSync(FIX('fixture-blocks-regular.ttf')), 'a.ttf');
  assert.deepEqual([a.format, a.family, a.subfamily, a.weight, a.style], ['ttf', 'Fixture Blocks', 'Regular', 400, 'normal']);
  assert.match(a.licenseText, /public domain/i);
  const bold = parseFont(readFileSync(FIX('fixture-blocks-bold.ttf')), 'b.ttf');
  assert.deepEqual([bold.weight, bold.style], [700, 'normal']);
  const slant = parseFont(readFileSync(FIX('fixture-slant.woff2')), 's.woff2');
  assert.deepEqual([slant.format, slant.family, slant.weight, slant.style], ['woff2', 'Fixture Slant', 600, 'italic']);
  const wide = parseFont(readFileSync(FIX('fixture-wide.otf')), 'w.otf');
  assert.deepEqual([wide.format, wide.family], ['otf', 'Fixture Wide']);

  const cov = summarizeCoverage(a.codepoints);
  assert.equal(cov.codepoints, 105); // 95 printable ASCII and ten Romanian letters
  assert.equal(cov.romanian, true);
  assert.equal(cov.latinExtendedA, false, 'only two letters of the block');
  assert.deepEqual(cov.blocks.map((b) => b.name), ['Basic Latin', 'Latin-1 Supplement', 'Latin Extended-A', 'Latin Extended-B']);
  assert.deepEqual(cov.ranges[0], [0x20, 0x7e]);
  const wideCov = summarizeCoverage(wide.codepoints);
  assert.equal(wideCov.latinExtendedA, true);
  assert.equal(wideCov.romanian, false, 'no comma-below letters');
});

test('parseFont refuses what is not a font, with a reason', () => {
  assert.throws(() => parseFont(Buffer.from('this is not a font file at all'), 'x.ttf'), /x\.ttf: not a font file \(unknown signature/);
  assert.throws(() => parseFont(Buffer.alloc(4), 'tiny.ttf'), /only 4 bytes/);
  const truncated = readFileSync(FIX('fixture-blocks-regular.ttf')).subarray(0, 300);
  assert.throws(() => parseFont(truncated, 'cut.ttf'), /cut\.ttf: not a font file/);
  // a cmap and nothing to draw
  assert.throws(() => parseFont(readFileSync(FIX('fixture-slant.woff2')).subarray(0, 40), 'short.woff2'), /not a font file/);
});

test('coverageReport takes the coverage of uploaded families, and an unknown one still draws nothing', () => {
  const extra = new Map([['fixture wide', parseFont(readFileSync(FIX('fixture-wide.otf')), 'w').codepoints]]);
  assert.deepEqual(coverageReport([{ text: 'Ā ș', family: 'Fixture Wide' }], extra).map((g) => g.char), ['ș']);
  assert.deepEqual(coverageReport([{ text: 'a', family: 'Fixture Wide' }]).map((g) => g.char), ['a']);
});

// ---- adding fonts ---------------------------------------------------------------------------------

test('a TTF becomes a font asset with its family, weight, style, licence and coverage', async () => {
  const r = await add({ name: 'fixture-blocks', path: FIX('fixture-blocks-regular.ttf'), license: 'CC0-1.0', source: 'scripts/make-test-fonts.mjs', licenseFile: FIX('LICENSE.txt') });
  const a = r.asset;
  assert.equal(a.ref, 'fixture-blocks@1');
  assert.equal(a.type, 'font');
  assert.equal(a.title, 'Fixture Blocks Regular');
  const m = a.meta;
  assert.deepEqual([m.family, m.weight, m.style, m.license, m.uploaded, m.format], ['Fixture Blocks', 400, 'normal', 'CC0-1.0', true, 'ttf']);
  assert.equal(m.source, 'scripts/make-test-fonts.mjs');
  assert.equal(m.bytes, readFileSync(FIX('fixture-blocks-regular.ttf')).length);
  assert.equal(m.sha256, createHash('sha256').update(readFileSync(FIX('fixture-blocks-regular.ttf'))).digest('hex'));
  assert.equal(m.coverage.codepoints, 105);
  assert.equal(m.coverage.romanian, true);
  assert.match(m.embeddedLicense, /public domain/i);
  assert.ok(existsSync(join(t.dataDir, a.file)) && a.file === 'files/fixture-blocks@1.ttf');
  assert.equal(readFileSync(join(t.dataDir, m.licenseFile), 'utf8'), readFileSync(FIX('LICENSE.txt'), 'utf8'));
  assert.equal(readFileSync(r.thumbPath).subarray(1, 4).toString(), 'PNG', 'a specimen drawn with the font');
  assert.ok(a.tags.includes('font') && a.tags.includes('uploaded'));
  assert.ok(a.description.includes('Fixture Blocks'));
  // searchable, listed, and a font parameter can name the family
  assert.equal(studio.library.search({ type: 'font', query: 'fixture' }).assets[0].ref, 'fixture-blocks@1');
  assert.ok(studio.library.fontFamilies().includes('Fixture Blocks'));
  assert.equal(studio.library.fontRef('fixture blocks'), 'fixture-blocks@1');
  assert.equal(studio.library.fontRef('Inter'), 'font-inter@1', 'bundled families are as they were');
});

test('a WOFF2 italic and an OTF are read the same way; two weights are two assets of one family', async () => {
  const w = (await add({ name: 'fixture-slant', path: FIX('fixture-slant.woff2'), license: 'CC0-1.0' })).asset;
  assert.deepEqual([w.meta.family, w.meta.weight, w.meta.style, w.meta.format, w.mime], ['Fixture Slant', 600, 'italic', 'woff2', 'font/woff2']);
  assert.equal(w.title, 'Fixture Slant Semi Bold Italic');
  assert.ok(w.tags.includes('italic'));
  const o = (await add({ name: 'fixture-wide', path: FIX('fixture-wide.otf'), license: 'CC0-1.0', tags: ['display'] })).asset;
  assert.deepEqual([o.meta.family, o.meta.format, o.meta.coverage.latinExtendedA, o.meta.coverage.romanian], ['Fixture Wide', 'otf', true, false]);
  assert.ok(o.tags.includes('display'));

  const bold = (await add({ name: 'fixture-blocks-bold', path: FIX('fixture-blocks-bold.ttf'), license: 'CC0-1.0' })).asset;
  assert.deepEqual([bold.meta.family, bold.meta.weight], ['Fixture Blocks', 700]);
  const fam = studio.fonts.listFonts().find((f) => f.family === 'Fixture Blocks');
  assert.deepEqual(fam.faces.map((x) => [x.ref, x.weight]), [['fixture-blocks@1', 400], ['fixture-blocks-bold@1', 700]]);
  assert.equal(fam.bundled, false);
  assert.equal(fam.faces[0].coverage.latinExtendedA, false);
  assert.ok(studio.fonts.listFonts().find((f) => f.family === 'Inter').bundled);
});

test('family, weight and style can be overridden; the family keeps its first spelling', async () => {
  const r = await add({ name: 'fixture-blocks-black', path: FIX('fixture-blocks-bold.ttf'), family: 'fixture BLOCKS', weight: 900, style: 'italic', title: 'Blocks Black' });
  assert.deepEqual([r.asset.meta.family, r.asset.meta.weight, r.asset.meta.style, r.asset.title], ['Fixture Blocks', 900, 'italic', 'Blocks Black']);
  await refused(add({ name: 'fixture-blocks-again', path: FIX('fixture-blocks-bold.ttf') }), /fixture-blocks-bold already provides Fixture Blocks 700 normal/);
  await refused(add({ name: 'x-weight', path: FIX('fixture-blocks-bold.ttf'), family: 'X Weight', weight: 1200 }), /weight is a whole number from 1 to 1000/);
  await refused(add({ name: 'x-style', path: FIX('fixture-blocks-bold.ttf'), family: 'X Style', style: 'oblique' }), /style is "normal" or "italic"/);
});

// ---- refusals -------------------------------------------------------------------------------------

test('a bundled family name is refused, and bundled fonts keep their versions', async () => {
  await refused(add({ name: 'my-inter', path: FIX('fixture-blocks-regular.ttf'), family: 'Inter' }), /Inter is bundled with the studio; give your font another family name/);
  await refused(add({ name: 'my-inter', path: FIX('fixture-blocks-regular.ttf'), family: 'playfair display' }), /Playfair Display is bundled with the studio/);
  await refused(add({ name: 'my-inter', path: FIX('fixture-blocks-regular.ttf'), family: 'Inter Ext' }), /Inter is bundled with the studio/);
  await refused(add({ name: 'font-inter', path: FIX('fixture-blocks-regular.ttf'), family: 'Not Inter' }), /font-inter" is a font bundled with the studio/);
  assert.equal(studio.library.search({ query: 'my-inter' }).total, 0, 'nothing was written');
});

test('a broken file, a missing licence, an oversized file and other bad input get useful errors', async () => {
  await refused(add({ name: 'broken', data: Buffer.from('not a font'.repeat(20)), originalName: 'broken.ttf' }), /broken\.ttf: not a font file \(unknown signature.*Add a TTF, OTF or WOFF2 font file/);
  await refused(add({ name: 'cut', data: readFileSync(FIX('fixture-blocks-regular.ttf')).subarray(0, 200), originalName: 'cut.ttf' }), /cut\.ttf: not a font file/);
  await refused(add({ name: 'nolic', path: FIX('fixture-blocks-regular.ttf'), license: '' }), /A licence is required.*"OFL-1\.1".*The file says: "Dedicated to the public domain/s);
  await refused(add({ name: 'nolic', path: FIX('fixture-blocks-regular.ttf'), license: undefined }), /A licence is required/);
  await refused(add({ name: 'big', data: Buffer.alloc(25_000_001), originalName: 'big.ttf' }), /big\.ttf is 25\.0 MB; font files are at most 25 MB/);
  await refused(add({ name: 'gone', path: join(t.dataDir, 'no-such.ttf') }), /File not found/);
  await refused(add({ name: 'Bad Name', path: FIX('fixture-blocks-regular.ttf') }), /not a valid asset name/);
  await refused(add({ name: 'nofile' }), /Give the font file/);
  await refused(add({ name: 'lic-gone', path: FIX('fixture-blocks-regular.ttf'), family: 'Lic Gone', licenseFile: join(t.dataDir, 'nope.txt') }), /license_file not found/);
  await refused(add({ name: 'woff1', data: Buffer.concat([Buffer.from('wOFF'), Buffer.alloc(60)]), originalName: 'old.woff' }), /not a font file|WOFF 1/);
  assert.equal(studio.library.search({ type: 'font', query: 'broken' }).total, 0);
  assert.deepEqual(filesIn(t.dataDir).filter((f) => f.startsWith('.tmp-')), [], 'no temp files are left behind');
});

// ---- it works at once ------------------------------------------------------------------------------

test('a clip draws an uploaded family at once in Node: no restart, different pixels from a bundled family', async () => {
  // a worker that already holds bundles (and so was started before the font was known) is used for both clips
  await studio.clips.createClip({ slug: 'in-inter', author: AUTHOR, composition: clipOf('Inter') });
  const inter = await hashOf('in-inter');
  const late = await add({ name: 'fixture-late', path: FIX('fixture-blocks-regular-v2.ttf'), family: 'Fixture Late', license: 'CC0-1.0' });
  assert.equal(late.asset.ref, 'fixture-late@1');
  const made = await studio.clips.createClip({ slug: 'in-blocks', author: AUTHOR, composition: clipOf('Fixture Blocks') });
  assert.deepEqual(made.clip.composition.fonts, { 'Fixture Blocks': ['fixture-blocks-black@1', 'fixture-blocks-bold@1', 'fixture-blocks@1'] }, 'every font asset of the family is pinned');
  const blocks = await hashOf('in-blocks');
  assert.notEqual(blocks, inter, 'the text is drawn with the uploaded font');
  assert.equal(await hashOf('in-blocks'), blocks, 'and the same way each time');
  // the pins are recorded as assets the clip uses
  const used = studio.clips.getClip('in-blocks').assets.map((x) => x.ref);
  for (const ref of ['fixture-blocks@1', 'fixture-blocks-bold@1', 'text@1']) assert.ok(used.includes(ref), `${ref} in clip_assets`);
  assert.equal(studio.clips.getClip('in-blocks').assets.find((x) => x.ref === 'fixture-blocks@1').relation, 'library');
  // the text really comes from the file: bars are as tall as the file says, so the frame has white pixels in bars, not letter shapes
  const png = (await studio.clipFrame({ clip: 'in-blocks', t: 1 })).png;
  assert.equal(png.subarray(1, 4).toString(), 'PNG');
  // a clip that names only bundled families is saved exactly as before: no fonts key
  assert.equal(studio.clips.getClip('in-inter').composition.fonts, undefined);
  // ... and the family that came later also works at once
  await studio.clips.createClip({ slug: 'in-late', author: AUTHOR, composition: clipOf('Fixture Late') });
  assert.notEqual(await hashOf('in-late'), blocks, 'a triangle font is not a bar font');
});

test('weights: bold text uses the bold file, regular text the regular one', async () => {
  const regular = await studio.frameHashes({ composition: clipOf('Fixture Blocks', { weight: 400 }), times: [1] });
  const bold = await studio.frameHashes({ composition: clipOf('Fixture Blocks', { weight: 700 }), times: [1] });
  assert.notEqual(regular[0].hash, bold[0].hash);
});

test('a family that is not in the library is refused with the families that are', async () => {
  await assert.rejects(studio.clips.createClip({ slug: 'nope', author: AUTHOR, composition: clipOf('Comic Nonesuch') }), (/** @type {any} */ e) => {
    assert.match(e.message, /unknown font family "Comic Nonesuch" \(available: Inter, .*Fixture Blocks.*Fixture Wide/);
    return true;
  });
});

test('asset frames use the latest files of an uploaded family', async () => {
  const a = await studio.assetFrame({ ref: 'text@1', params: { text: 'Hello', font: 'Fixture Blocks' }, width: 320, height: 180, hash: true });
  const b = await studio.assetFrame({ ref: 'text@1', params: { text: 'Hello', font: 'Inter' }, width: 320, height: 180, hash: true });
  assert.notEqual(a.hash, b.hash);
});

// ---- coverage in the checks ------------------------------------------------------------------------

test('the glyph findings read the pinned font files', async () => {
  // Fixture Wide has no ș or ț; Fixture Blocks has
  const wide = await studio.clips.check((await studio.clips.prepare(clipOf('Fixture Wide', { text: 'Ă ș' }))).composition);
  assert.equal(wide.missingGlyphs.length, 1, JSON.stringify(wide));
  assert.match(wide.missingGlyphs[0], /ș \(U\+0219, letter\) is not in Fixture Wide/);
  const blocks = await studio.clips.check((await studio.clips.prepare(clipOf('Fixture Blocks', { text: 'Ă ș 漢' }))).composition);
  assert.equal(blocks.missingGlyphs.length, 1);
  assert.match(blocks.missingGlyphs[0], /漢.*is not in Fixture Blocks/);
  // the layout report names the real family, not the alias
  const report = await studio.inspect.layoutReport({ composition: clipOf('Fixture Blocks'), t: 1 });
  assert.equal(report.texts[0].family, 'Fixture Blocks');
});

// ---- pinning ---------------------------------------------------------------------------------------

test('a new version of a font leaves a clip drawing the version it was made with; a repinned clip draws the new one', async () => {
  const v1 = await hashOf('in-blocks');
  const v2 = await add({ name: 'fixture-blocks', path: FIX('fixture-blocks-regular-v2.ttf'), license: 'CC0-1.0', note: 'triangles' });
  assert.equal(v2.asset.ref, 'fixture-blocks@2');
  assert.equal(v2.asset.latestVersion, 2);
  assert.deepEqual(v2.asset.versions.map((v) => v.version), [1, 2]);
  assert.notEqual(v2.asset.meta.sha256, studio.library.getAsset('fixture-blocks@1').meta.sha256);

  // the clip still draws version 1: same pins, same pixels
  assert.equal(studio.clips.getClip('in-blocks').composition.fonts['Fixture Blocks'].includes('fixture-blocks@1'), true);
  assert.equal(await hashOf('in-blocks'), v1, 'frame hash unchanged');
  // saving the clip again keeps the pin
  await studio.clips.updateClip('in-blocks', { composition: studio.clips.getClip('in-blocks').composition });
  assert.ok(studio.clips.getClip('in-blocks').composition.fonts['Fixture Blocks'].includes('fixture-blocks@1'));
  assert.equal(await hashOf('in-blocks'), v1);

  // a new clip pins the latest; repinning a copy moves it too
  await studio.clips.createClip({ slug: 'new-blocks', author: AUTHOR, composition: clipOf('Fixture Blocks') });
  assert.ok(studio.clips.getClip('new-blocks').composition.fonts['Fixture Blocks'].includes('fixture-blocks@2'));
  const v2hash = await hashOf('new-blocks');
  assert.notEqual(v2hash, v1);
  await studio.clips.repinClip({ slug: 'in-blocks', newSlug: 'in-blocks-latest', author: AUTHOR });
  assert.ok(studio.clips.getClip('in-blocks-latest').composition.fonts['Fixture Blocks'].includes('fixture-blocks@2'));
  assert.equal(await hashOf('in-blocks-latest'), v2hash, 'draws version 2');
  assert.equal(await hashOf('in-blocks'), v1, 'the original is untouched');
  // repin in place, by asset name
  await studio.clips.repinClip(/** @type {any} */ ({ slug: 'in-blocks' }));
  assert.ok(studio.clips.getClip('in-blocks').composition.fonts['Fixture Blocks'].includes('fixture-blocks@2'));
  assert.equal(await hashOf('in-blocks'), v2hash);
  // the same file again is not a new version
  await refused(add({ name: 'fixture-blocks', path: FIX('fixture-blocks-regular-v2.ttf'), license: 'CC0-1.0' }), /identical to fixture-blocks@2/);
});

test('the pinned fonts are part of the bundle a worker loads: aliases name the exact files', async () => {
  const comp = studio.clips.getClip('new-blocks').composition;
  const { bundle } = await studio.clips.bundleFor(comp);
  const [alias] = Object.keys(bundle.fonts);
  assert.match(alias, /^fc-[0-9a-f]{8}$/);
  assert.equal(bundle.fonts[alias].family, 'Fixture Blocks');
  assert.deepEqual(bundle.fonts[alias].files.map((f) => [f.ref, f.weight, f.style]), [['fixture-blocks-black@1', 900, 'italic'], ['fixture-blocks-bold@1', 700, 'normal'], ['fixture-blocks@2', 400, 'normal']]);
  assert.ok(bundle.fonts[alias].files.every((f) => existsSync(f.path)));
  // another pin, another alias and another bundle key
  const old = await studio.clips.bundleFor(studio.clips.getClip('in-blocks-latest').composition);
  assert.equal(Object.keys(old.bundle.fonts)[0], alias);
  const pinnedV1 = { ...comp, fonts: { 'Fixture Blocks': ['fixture-blocks@1', 'fixture-blocks-bold@1', 'fixture-blocks-black@1'] } };
  const v1 = await studio.clips.bundleFor(pinnedV1);
  assert.notEqual(Object.keys(v1.bundle.fonts)[0], alias);
  assert.notEqual(v1.bundle.key, bundle.key);
  // a bundle without uploaded fonts has no fonts key
  assert.equal((await studio.clips.bundleFor(studio.clips.getClip('in-inter').composition)).bundle.fonts, undefined);
});

test('a clip that drops the uploaded font drops its pins; bad pins in a composition are named', async () => {
  const back = await studio.clips.updateClip('in-blocks-latest', { composition: clipOf('Inter') });
  assert.equal(back.clip.composition.fonts, undefined);
  assert.throws(() => studio.clips.prepare({ ...clipOf('Fixture Blocks'), fonts: { 'Fixture Blocks': ['fixture-blocks@9'] } }), /font "Fixture Blocks": no font asset "fixture-blocks@9"/);
  assert.throws(() => studio.clips.prepare({ ...clipOf('Fixture Blocks'), fonts: { 'Fixture Blocks': ['text@1'] } }), /text@1 is not an uploaded font/);
  assert.throws(() => studio.clips.prepare({ ...clipOf('Fixture Blocks'), fonts: { 'Fixture Blocks': 'x' } }), /fonts maps a font family/);
});

// ---- the text library ------------------------------------------------------------------------------

test('fontString puts the alias of the pinned set first, and only for families the clip pinned', () => {
  const aliases = fontAliases({ 'fc-ab12cd34': { family: 'Acme Sans' } });
  assert.deepEqual(aliases, { 'acme sans': 'fc-ab12cd34' });
  assert.match(fontString({ font: 'Acme Sans', size: 40, weight: 700, aliases }), /^700 40px "fc-ab12cd34", "Acme Sans", "Acme Sans Ext", /);
  assert.match(fontString({ font: 'acme sans', size: 40, aliases }), /^400 40px "fc-ab12cd34", "acme sans", /);
  assert.equal(fontString({ font: 'Inter', size: 40, weight: 800, aliases }), fontString({ font: 'Inter', size: 40, weight: 800 }), 'bundled families are as before');
  assert.equal(fontString({ font: 'constructor', aliases }), fontString({ font: 'constructor' }));
  assert.equal(familyOf(fontString({ font: 'Acme Sans', aliases })), 'Acme Sans');
  assert.equal(familyOf('40px "Inter", sans-serif'), 'Inter');
  assert.equal(fontAliases(undefined), null);
});

test('layouts are cached per set of pinned files: the same text under another alias is laid out again', () => {
  const inspect = { record: null, suppress: false, frame: null, floor: 0, fonts: null };
  const text = createText(inspect);
  const ctx = createCanvas(200, 100).getContext('2d');
  const plain = text.layout(ctx, 'Hello', { font: 'Inter', size: 30 });
  assert.equal(text.layout(ctx, 'Hello', { font: 'Inter', size: 30 }), plain, 'cached');
  inspect.fonts = { inter: 'fc-00000001' };
  const pinned = text.layout(ctx, 'Hello', { font: 'Inter', size: 30 });
  assert.notEqual(pinned, plain);
  assert.match(pinned.font, /"fc-00000001", "Inter"/);
  inspect.fonts = { inter: 'fc-00000002' };
  assert.match(text.layout(ctx, 'Hello', { font: 'Inter', size: 30 }).font, /"fc-00000002"/);
  inspect.fonts = { 'acme sans': 'fc-00000003' };
  assert.equal(text.layout(ctx, 'Hello', { font: 'Inter', size: 30 }), plain, 'an unrelated mapping changes nothing');
  assert.equal(text.fontString({ font: 'Acme Sans', size: 10 }).includes('fc-00000003'), true);
});

// ---- old compositions ------------------------------------------------------------------------------

test('old compositions with bundled fonts save to identical JSON and draw identical pixels', async () => {
  // recorded with the code before fonts could be uploaded: the clip made by this test, in a studio with no uploaded font
  const fresh = tempStudio();
  try {
    await fresh.studio.library.createAsset({ slug: 'easing', source: EASING, author: AUTHOR });
    await fresh.studio.library.createAsset({ slug: 'label', source: LABEL, author: AUTHOR });
    const items = ['Inter', 'Playfair Display', 'Anton', 'JetBrains Mono', 'Space Grotesk'].map((font, i) => ({ id: `t${i}`, asset: 'label', start: 0, duration: 2, params: { text: `Hello ${font} ăș`, font }, box: { x: 0, y: i * 0.2, width: 1, height: 0.2 } }));
    const made = await fresh.studio.clips.createClip({ slug: 'old', author: AUTHOR, composition: { width: 320, height: 180, fps: 10, duration: 2, tracks: [{ id: 'v', type: 'visual', items }] } });
    const before = JSON.stringify(made.clip.composition);
    assert.equal(createHash('sha256').update(before).digest('hex'), '2c83b25de509276beb8957d49815e4cd334a1d9b57960cada06a5dee994deded', 'the JSON is what it was');
    assert.ok(!('fonts' in made.clip.composition));
    const h0 = (await fresh.studio.frameHashes({ clip: 'old', times: [0.5, 1] })).map((h) => h.hash);
    // saved again, in place and through a repin: nothing changes
    await fresh.studio.clips.updateClip('old', { composition: made.clip.composition });
    assert.equal(JSON.stringify(fresh.studio.clips.getClip('old').composition), before);
    await fresh.studio.clips.repinClip(/** @type {any} */ ({ slug: 'old' }));
    assert.equal(JSON.stringify(fresh.studio.clips.getClip('old').composition), before);
    // and after a font was uploaded into the same studio, the clip still draws the same pixels
    await fresh.studio.fonts.addFont({ name: 'fixture-blocks', path: FIX('fixture-blocks-regular.ttf'), license: 'CC0-1.0', author: AUTHOR });
    assert.deepEqual((await fresh.studio.frameHashes({ clip: 'old', times: [0.5, 1] })).map((h) => h.hash), h0);
    // the pixels of the same clip as drawn by the code before this change (hashes are per machine: only compared where recorded)
    if (process.platform === 'win32') assert.equal(h0[0], '5f00f79fb6ff155b8a60b45fe1f946244f6f2480d63581b1e7d25dfa7b8681ed');
  } finally { await fresh.cleanup(); }
});

// ---- the browser ------------------------------------------------------------------------------------

test('the browser bundle carries the font URLs and the alias; the files are served; the upload route works', async () => {
  const server = /** @type {any} */ (createStudioServer(studio));
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  try {
    const clip = await (await fetch(`${base}/api/clips/new-blocks`)).json();
    const [alias] = Object.keys(clip.bundle.fonts);
    assert.match(alias, /^fc-[0-9a-f]{8}$/);
    const set = clip.bundle.fonts[alias];
    assert.equal(set.family, 'Fixture Blocks');
    assert.deepEqual(set.files.map((f) => [f.ref, f.url, f.weight, f.style]), [
      ['fixture-blocks-black@1', '/media/files/fixture-blocks-black@1.ttf', 900, 'italic'],
      ['fixture-blocks-bold@1', '/media/files/fixture-blocks-bold@1.ttf', 700, 'normal'],
      ['fixture-blocks@2', '/media/files/fixture-blocks@2.ttf', 400, 'normal'],
    ]);
    assert.ok(set.files.every((f) => !('path' in f)), 'no server paths reach the browser');
    assert.deepEqual(clip.composition.fonts['Fixture Blocks'].length, 3);
    // the font file is served with its type
    const file = await fetch(`${base}${set.files[2].url}`);
    assert.equal(file.status, 200);
    assert.equal(file.headers.get('content-type'), 'font/ttf');
    assert.deepEqual(Buffer.from(await file.arrayBuffer()), readFileSync(FIX('fixture-blocks-regular-v2.ttf')));
    // a draft bundle (the editor posts these) pins the same way; a bundled-only clip has no fonts
    const draft = await (await fetch(`${base}/api/clips/new-blocks/bundle`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ composition: clipOf('Fixture Wide') }) })).json();
    assert.equal(Object.values(draft.bundle.fonts)[0].files[0].url, '/media/files/fixture-wide@1.otf');
    assert.equal((await (await fetch(`${base}/api/clips/in-inter`)).json()).bundle.fonts, undefined);
    // the menus list the uploaded families (without files: the clip's bundle brings what it pins)
    const status = await (await fetch(`${base}/api/status`)).json();
    const listed = status.fonts.find((f) => f.family === 'Fixture Wide');
    assert.deepEqual([listed.uploaded, listed.files], [true, []]);
    assert.equal(status.fonts.find((f) => f.family === 'Inter').files.length, 3);

    // upload over HTTP: the raw file as the body
    const up = await fetch(`${base}/api/fonts?name=http-font&license=OFL-1.1&family=Http%20Font&weight=500`, { method: 'POST', headers: { 'content-type': 'font/ttf' }, body: readFileSync(FIX('fixture-blocks-bold.ttf')) });
    const upBody = await up.json();
    assert.equal(up.status, 200, JSON.stringify(upBody));
    assert.equal(upBody.asset.ref, 'http-font@1');
    assert.deepEqual([upBody.asset.meta.family, upBody.asset.meta.weight, upBody.asset.meta.license], ['Http Font', 500, 'OFL-1.1']);
    assert.equal(upBody.coverage.romanian, true);
    assert.equal((await fetch(`${base}${upBody.thumb}`)).status, 200);
    const list = await (await fetch(`${base}/api/fonts`)).json();
    assert.ok(list.fonts.some((f) => f.family === 'Http Font' && f.faces[0].ref === 'http-font@1'));
    assert.ok(list.fonts.some((f) => f.family === 'Inter' && f.bundled));
    // errors a client can cause
    const bad = (query, body, type = 'application/octet-stream') => fetch(`${base}/api/fonts?${query}`, { method: 'POST', headers: { 'content-type': type }, body });
    let r = await bad('name=x-font&license=OFL-1.1', Buffer.from('nope, not a font at all'));
    assert.equal(r.status, 422); assert.match((await r.json()).error, /not a font file/);
    r = await bad('name=x-font', readFileSync(FIX('fixture-blocks-bold.ttf')));
    assert.equal(r.status, 400); assert.match((await r.json()).error, /A licence is required/);
    r = await bad('name=x-font&license=OFL-1.1&family=Inter', readFileSync(FIX('fixture-blocks-bold.ttf')));
    assert.equal(r.status, 409); assert.match((await r.json()).error, /Inter is bundled with the studio/);
    r = await bad('name=x-font&license=OFL-1.1', readFileSync(FIX('fixture-blocks-bold.ttf')), 'application/json');
    assert.equal(r.status, 415);
    r = await bad('name=x-font&license=OFL-1.1', Buffer.alloc(26_000_000));
    assert.equal(r.status, 413); assert.match((await r.json()).error, /larger than 25 MB/);
    assert.equal((await bad('name=x-font&license=OFL-1.1', Buffer.alloc(0))).status, 422);
  } finally {
    server.closeAllConnections();
    await new Promise((resolve) => server.close(resolve));
  }
});

// ---- MCP over stdio --------------------------------------------------------------------------------

test('MCP: add_font and list_fonts over stdio', async () => {
  const dataDir = mkdtempSync(join(process.env.TMPDIR ?? tmpdir(), 'studio-fonts-mcp-'));
  const client = await connect({ dataDir, author: 'mcp-font-model' });
  const call = (name, args) => callTool(client, name, args);
  try {
    const { tools } = await client.listTools();
    for (const n of ['add_font', 'list_fonts']) assert.ok(tools.some((x) => x.name === n), `missing ${n}`);
    assert.deepEqual(tools.find((x) => x.name === 'add_font').inputSchema.required.sort(), ['license', 'name', 'path']);

    const ttf = await call('add_font', { path: FIX('fixture-blocks-regular.ttf'), name: 'mcp-blocks', license: 'CC0-1.0', license_file: FIX('LICENSE.txt'), source: 'https://example.test/fixture' });
    assert.ok(!ttf.isError, ttf.text);
    assert.deepEqual([ttf.json.added, ttf.json.family, ttf.json.weight, ttf.json.style, ttf.json.license, ttf.json.format], ['mcp-blocks@1', 'Fixture Blocks', 400, 'normal', 'CC0-1.0', 'ttf']);
    assert.equal(ttf.json.coverage.codepoints, 105);
    assert.equal(ttf.json.coverage.latinExtendedA, false);
    assert.equal(ttf.json.coverage.romanian, true);
    assert.ok(ttf.json.coverage.blocks.includes('Basic Latin 95/95'));
    assert.match(ttf.json.licenseFile, /^files\/mcp-blocks@1\.license\.txt$/);
    assert.equal(ttf.images.length, 1);
    assert.equal(ttf.images[0].subarray(1, 4).toString(), 'PNG');

    const woff2 = await call('add_font', { path: FIX('fixture-slant.woff2'), name: 'mcp-slant', license: 'CC0-1.0', tags: ['display'] });
    assert.ok(!woff2.isError, woff2.text);
    assert.deepEqual([woff2.json.family, woff2.json.weight, woff2.json.style, woff2.json.format], ['Fixture Slant', 600, 'italic', 'woff2']);

    // a new version, then the asset as get_asset shows it
    const v2 = await call('add_font', { path: FIX('fixture-blocks-regular-v2.ttf'), name: 'mcp-blocks', license: 'CC0-1.0', note: 'triangles' });
    assert.equal(v2.json.added, 'mcp-blocks@2');
    const got = await call('get_asset', { ref: 'mcp-blocks@1' });
    assert.deepEqual([got.json.type, got.json.meta.family, got.json.meta.uploaded], ['font', 'Fixture Blocks', true]);
    assert.equal(got.json.versions.length, 2);

    const list = await call('list_fonts', {});
    const fam = list.json.fonts.find((f) => f.family === 'Fixture Blocks');
    assert.deepEqual([fam.bundled, fam.faces[0].ref, fam.faces[0].weight, fam.faces[0].license], [false, 'mcp-blocks@2', 400, 'CC0-1.0']);
    assert.ok(list.json.fonts.find((f) => f.family === 'Inter').bundled);
    const found = await call('search_assets', { type: 'font', query: 'slant' });
    assert.equal(found.json.assets[0].ref, 'mcp-slant@1');

    // errors come back as tool errors, and the server carries on
    const noLicense = await call('add_font', { path: FIX('fixture-blocks-bold.ttf'), name: 'mcp-bold', license: ' ' });
    assert.ok(noLicense.isError); assert.match(noLicense.text, /A licence is required/);
    const bundled = await call('add_font', { path: FIX('fixture-blocks-bold.ttf'), name: 'mcp-bold', license: 'CC0-1.0', family: 'Space Grotesk' });
    assert.ok(bundled.isError); assert.match(bundled.text, /Space Grotesk is bundled with the studio; give your font another family name/);
    const broken = join(dataDir, 'broken.ttf');
    writeFileSync(broken, 'definitely not a font');
    const bad = await call('add_font', { path: broken, name: 'mcp-bad', license: 'CC0-1.0' });
    assert.ok(bad.isError); assert.match(bad.text, /broken\.ttf: not a font file/);
    assert.ok(!(await call('list_fonts', {})).isError, 'still answering');

    // a clip made through MCP pins the font; the frame draws with it
    for (const [name, source] of [['easing', EASING], ['text', TEXT]]) assert.ok(!(await call('create_asset', { name, source })).isError);
    const clip = await call('create_clip', { name: 'mcp-font-clip', composition: { ...clipOf('Fixture Blocks') } });
    assert.ok(!clip.isError, clip.text);
    const comp = (await call('get_clip', { clip: 'mcp-font-clip' })).json.composition;
    assert.deepEqual(comp.fonts, { 'Fixture Blocks': ['mcp-blocks@2'] });
    const frame = await call('render_clip_frame', { clip: 'mcp-font-clip', t: 1 });
    assert.ok(!frame.isError, frame.text);
    assert.equal(frame.images[0].subarray(1, 4).toString(), 'PNG');
  } finally {
    await client.close();
    await new Promise((r) => setTimeout(r, 300));
    try { rmSync(dataDir, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 }); } catch { /* Windows may still hold the db file */ }
  }
});
